import {hasLiveTask} from './fleet-tasks.js';
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const taskStatusText=r=>r?.task?'SURVEY / '+r.task.state+' · '+r.task.stage:'NO AUTONOMOUS JOB';
export function renderFleetTask(record,{enabled=true,blocked=''}={}){
 const t=record.task,live=hasLiveTask(record),button=(action,label,disabled=false)=>`<button data-fleet-task="${action}" ${!enabled||disabled?'disabled':''}>${label}</button>`;
 return `<section class="fleetTask" aria-label="Selected aircraft task"><div class="sectionHeading"><span>AUTONOMY / ${esc(record.type.toUpperCase())}</span><b>${t?esc(t.state):'READY'}</b></div><h3>Survey ahead & return</h3><p>Fly to a fixed point roughly 70 m ahead of the bike, hold steady for 5 seconds, scan (3% charge), then physically return. No quest items or power are collected.</p>${t?`<p class="taskBadge">${esc(taskStatusText(record))}</p><p role="status">${esc(t.reason)}</p>`:''}<div class="taskActions">${button('assign','ASSIGN SURVEY',live)}${live?(t.state==='PAUSED'?button('resume','RESUME JOB'):button('pause','PAUSE / HOLD'))+button('cancel','CANCEL & RETURN'):''}</div><p class="hint">${esc(blocked||'Jobs run only while play is resumed. FPV / HOLD pauses the job; recall cancels it. Safety returns never auto-resume.')}</p>${t?`<details><summary>Task details</summary><dl><dt>Aircraft / battery</dt><dd>${esc(record.id)} / ${esc(record.batteryId)}</dd><dt>Job</dt><dd>${esc(t.id)}</dd><dt>Fixed waypoint (m)</dt><dd>${t.destination.map(n=>n.toFixed(1)).join(' / ')}</dd><dt>Active time / contacts</dt><dd>${Math.floor(t.elapsed)} s / ${t.contacts}</dd></dl></details>`:''}</section>`;
}
